local MAX_MAG=50
local cam={
	x=0,
	y=0
}
local ply={
	x=0,
	y=0,
	moving=false,
	vx=0,
	vy=0,
	course=0,
	stroke=1
}
local courses={
	{
		par=2,
		x=16,
		y=16,
		player=0
	},
	{
		par=3,
		x=40,
		y=19,
		player=0
	},
	{
		par=4,
		x=41,
		y=27,
		player=0
	},
	{
		par=6,
		x=30,
		y=34,
		player=0
	}
}

local function print_hx(text,y)
	print(text,120-#text*4,y)
end

local game_done=false
local function next_hole(same)
	if ply.course>0 then
		courses[ply.course].player=ply.stroke
	end
	if not same then ply.course=ply.course+1 end
	if ply.course>#courses then
		game_done=true
		return
	end
	ply.vx=0
	ply.vy=0
	ply.moving=false
	ply.stroke=1
	ply.x=courses[ply.course].x
	ply.y=courses[ply.course].y
end
next_hole()

local t=0
function TIC()
	t=t+1
	if game_done then
		cls(4)
		print("The game is now done",32,16)
		local score=0
		for i,course in ipairs(courses) do
			print("Hole "..i..": "..course.player.." ("..course.player-course.par..")",32,24+i*10)
			score=score+(course.player-course.par)
		end
		print("YOUR SCORE:",32,104,6)
		print(score,32+11*8,104)
		
		local judgement="COOL!"
		if score>=3 then judgement="Hmm! :)" end
		if score<=-3 then judgement="Waow" end
		print("MAGISTRATE'S JUDGEMENT: "..judgement,32,112)
		return
	end

	ply.x=ply.x+ply.vx
	ply.y=ply.y+ply.vy
	ply.vx=ply.vx*0.95
	ply.vy=ply.vy*0.95
	if ply.x<0 then ply.x=0 end
	if ply.y<0 then ply.y=0 end
	if ply.x>1088 then ply.x=1088 end
	if ply.y>1028 then ply.y=1028 end

	local px=ply.x-cam.x+116
	local py=ply.y-cam.y+64
	local pcourse=courses[ply.course]

	-- map drawing
	cls(0)
	-- origin point (player at center)
	local mx=ply.x*8-124
	local my=ply.y*8-64
	map(mx/8,my/8,32,19,-(mx%8),-(my%8))
	--map(ply.x-15,ply.y-7)

	-- mouse
	local magsq=ply.vx*ply.vx+ply.vy*ply.vy
	if not ply.moving then
		local mx,my,lmb=mouse()

		-- normalize & clamp
		local mpx=mx-px-4
		local mpy=my-py-4
		local mouse_mag=math.sqrt(mpx*mpx+mpy*mpy)
		local mnx=mpx/mouse_mag
		local mny=mpy/mouse_mag
		if mouse_mag>MAX_MAG then
			mpx=mnx*MAX_MAG
			mpy=mny*MAX_MAG
		end

		line(px+4,py+4,px+mpx+4,py+mpy+4,14)
		if lmb then
			ply.moving=true
			ply.vx=mpx/48
			ply.vy=mpy/48
		end
	elseif magsq<=0.01 and ply.moving then
		ply.moving=false
		ply.vx=0
		ply.vy=0
		ply.stroke=ply.stroke+1
	end
	spr(1,px,py)

	-- collision
	local coll=mget(math.floor(ply.x+ply.vx),math.floor(ply.y+ply.vy))
	if fget(coll,0) then
		ply.vx=ply.vx*-0.8
		ply.vy=ply.vy*-0.8
	elseif coll==33 or fget(coll,1) then
		-- flagpole
		next_hole()
	end

	-- move camera to center of player
	local dx=ply.x-cam.x
	local dy=ply.y-cam.y
	if math.abs(dx)>0.1 then
		cam.x=cam.x+dx/4
	end
	if math.abs(dy)>0.1 then
		cam.y=cam.y+dy/4
	end

	-- status
	print_hx("Par "..pcourse.par,8)
	print_hx("Stroke "..ply.stroke,16)
	print("X to restart hole",8,120)
	if btnp(5) then next_hole(true) end
end

